//! Acceptance 4: the console request boundary matches Python.
//!
//! Every expected status and body comes from
//! `tests/fixtures/rust_console_rev1.json`; the fixture is generated by
//! running the real Python `usagesrv.Handler`.

mod support;

use serde_json::Value;

use support::*;

fn assert_case(response: &ClientResponse, case: &Value, name: &str) {
    assert_eq!(
        u64::from(response.status),
        case["status"].as_u64().unwrap(),
        "{name}"
    );
    assert_eq!(response.json(), case["body"], "{name}");
}

fn assert_closing_case(response: &ClientResponse, case: &Value, name: &str) {
    assert_case(response, case, name);
    assert_eq!(
        response.header("connection"),
        Some("close"),
        "{name} must close after the single response"
    );
}

#[test]
fn duplicate_sensitive_headers_match_python() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);

    let duplicate_header = client_request(
        console.addr,
        &ClientRequest::get("/api/console/services")
            .header("X-Admin-Control", "a")
            .header("X-Admin-Control", "b"),
    )
    .expect("duplicate header");
    assert_closing_case(
        &duplicate_header,
        &fixture["boundary"]["duplicateHeader"],
        "duplicateHeader",
    );

    let duplicate_content_type = client_request(
        console.addr,
        &ClientRequest::post("/api/console/operations", b"{}")
            .header("Content-Type", "application/json")
            .header("Content-Type", "application/json"),
    )
    .expect("duplicate content type");
    assert_closing_case(
        &duplicate_content_type,
        &fixture["boundary"]["duplicateContentType"],
        "duplicateContentType",
    );

    let duplicate_content_length = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", b"{}")
            .header("Content-Length", "2")
            .header("Content-Length", "2")
            .without_content_length(),
    )
    .expect("duplicate content length");
    assert_closing_case(
        &duplicate_content_length,
        &fixture["boundary"]["duplicateContentLength"],
        "duplicateContentLength",
    );
}

#[test]
fn request_body_gate_cases_match_python() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);

    let invalid_content_length = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", Vec::new())
            .header("Content-Length", "not-a-number")
            .without_content_length(),
    )
    .expect("invalid content length");
    assert_closing_case(
        &invalid_content_length,
        &fixture["boundary"]["invalidContentLength"],
        "invalidContentLength",
    );

    let too_large = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", Vec::new())
            .header("Content-Length", "65537")
            .without_content_length(),
    )
    .expect("too large");
    assert_closing_case(&too_large, &fixture["boundary"]["tooLarge"], "tooLarge");

    let transfer_encoding = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", Vec::new())
            .header("Transfer-Encoding", "chunked")
            .without_content_length(),
    )
    .expect("transfer encoding");
    assert_closing_case(
        &transfer_encoding,
        &fixture["boundary"]["transferEncoding"],
        "transferEncoding",
    );

    let content_encoding = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", Vec::new())
            .header("Content-Encoding", "gzip")
            .without_content_length(),
    )
    .expect("content encoding");
    assert_closing_case(
        &content_encoding,
        &fixture["boundary"]["contentEncoding"],
        "contentEncoding",
    );

    let missing_content_type = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", b"{}")
            .header("Content-Length", "2")
            .without_content_length(),
    )
    .expect("missing content type");
    assert_closing_case(
        &missing_content_type,
        &fixture["boundary"]["missingContentType"],
        "missingContentType",
    );

    let wrong_content_type = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", b"{}")
            .header("Content-Length", "2")
            .header("Content-Type", "text/plain")
            .without_content_length(),
    )
    .expect("wrong content type");
    assert_closing_case(
        &wrong_content_type,
        &fixture["boundary"]["wrongContentType"],
        "wrongContentType",
    );

    let invalid_json = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", b"{").json_body(b"{".to_vec()),
    )
    .expect("invalid json");
    assert_closing_case(
        &invalid_json,
        &fixture["boundary"]["invalidJson"],
        "invalidJson",
    );

    let non_object = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", b"[]").json_body(b"[]".to_vec()),
    )
    .expect("non object");
    assert_closing_case(&non_object, &fixture["boundary"]["nonObject"], "nonObject");

    let null_body = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", b"null").json_body(b"null".to_vec()),
    )
    .expect("null body");
    assert_case(&null_body, &fixture["boundary"]["nullBody"], "nullBody");
}

#[test]
fn declared_too_large_is_rejected_before_reading_the_body() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);
    let response = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", Vec::new())
            .header("Content-Length", "65537")
            .without_content_length(),
    )
    .expect("declared too large");
    assert_closing_case(
        &response,
        &fixture["boundary"]["tooLarge"],
        "declaredTooLarge",
    );
}

#[test]
fn unknown_fields_match_python() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);
    let body = br#"{"unknown":1}"#;
    let response = client_request(
        console.addr,
        &ClientRequest::post("/api/console/operations", body.to_vec()).json_body(body.to_vec()),
    )
    .expect("unknown fields");
    assert_case(
        &response,
        &fixture["boundary"]["unknownFields"],
        "unknownFields",
    );
    assert_eq!(
        response.header("connection"),
        None,
        "a fully read body keeps the connection open like Python"
    );
}

#[test]
fn empty_post_and_foreign_origin_match_python() {
    let fixture = fixture();
    let temp = temp();
    let console = start_console(&temp);

    let empty_post = client_request(
        console.addr,
        &ClientRequest::post("/api/console/services", Vec::new()),
    )
    .expect("empty post");
    assert_case(&empty_post, &fixture["boundary"]["emptyPost"], "emptyPost");

    let foreign_host = client_request(
        console.addr,
        &ClientRequest::get("/api/console/services").header("Host", "evil.example"),
    )
    .expect("foreign host");
    assert_eq!(
        u64::from(foreign_host.status),
        fixture["boundary"]["foreignHost"]["status"]
            .as_u64()
            .unwrap()
    );
    assert_eq!(
        foreign_host.json(),
        fixture["boundary"]["foreignHost"]["body"]
    );

    let foreign_origin = client_request(
        console.addr,
        &ClientRequest::get("/api/console/services").header("Origin", "http://127.0.0.1:8001"),
    )
    .expect("foreign origin");
    assert_eq!(
        u64::from(foreign_origin.status),
        fixture["boundary"]["foreignOrigin"]["status"]
            .as_u64()
            .unwrap()
    );
    assert_eq!(
        foreign_origin.json(),
        fixture["boundary"]["foreignOrigin"]["body"]
    );
}
